CREATE TABLE re.job_runner (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL UNIQUE,
    -- type VARCHAR(255) NOT NULL,
    description TEXT,
    ticker_list_name VARCHAR(255) NOT NULL,
    rules TEXT NOT NULL,
    
    CONSTRAINT fk_job_runner_ticker_list 
        FOREIGN KEY (ticker_list_name) 
        REFERENCES re.ticker_list(name) 
        ON DELETE RESTRICT ON UPDATE CASCADE
);



